B.a8L=new A.j(B.l,["\ubcf8 \uc57d\uad00\uc740 GKE STUDYUP \uc11c\ube44\uc2a4\uc758 \uc774\uc6a9 \uc870\uac74 \ubc0f \uc808\ucc28\ub97c \uaddc\uc815\ud569\ub2c8\ub2e4.","This agreement outlines the terms and procedures for using GKE STUDYUP services.","\u672c\u898f\u7d04\u306fGKE STUDYUP\u30b5\u30fc\u30d3\u30b9\u306e\u5229\u7528\u6761\u4ef6\u304a\u3088\u3073\u624b\u7d9a\u304d\u3092\u5b9a\u3081\u308b\u3082\u306e\u3067\u3059\u3002","\u672c\u534f\u8bae\u89c4\u5b9a\u4e86\u4f7f\u7528GKE STUDYUP\u670d\u52a1\u7684\u6761\u6b3e\u548c\u7a0b\u5e8f\u3002","Cet accord d\xe9finit les conditions et proc\xe9dures d'utilisation des services GKE STUDYUP.","Diese Vereinbarung legt die Bedingungen und Verfahren f\xfcr die Nutzung der GKE STUDYUP-Dienste fest.","\u041d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0438 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0441\u0435\u0440\u0432\u0438\u0441\u043e\u0432 GKE STUDYUP.","\u062a\u0648\u0636\u062d \u0647\u0630\u0647 \u0627\u0644\u0627\u062a\u0641\u0627\u0642\u064a\u0629 \u0634\u0631\u0648\u0637 \u0648\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062e\u062f\u0645\u0627\u062a GKE STUDYUP.","\u092f\u0939 \u0938\u092e\u091d\u094c\u0924\u093e GKE STUDYUP \u0938\u0947\u0935\u093e\u0913\u0902 \u0915\u0947 \u0909\u092a\u092f\u094b\u0917 \u0915\u0940 \u0936\u0930\u094d\u0924\u094b\u0902 \u0914\u0930 \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e\u0913\u0902 \u0915\u094b \u0930\u0947\u0916\u093e\u0902\u0915\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948\u0964","Th\u1ecfa thu\u1eadn n\xe0y quy \u0111\u1ecbnh c\xe1c \u0111i\u1ec1u kho\u1ea3n v\xe0 quy tr\xecnh s\u1eed d\u1ee5ng d\u1ecbch v\u1ee5 GKE STUDYUP.","Este acuerdo describe los t\xe9rminos y procedimientos para usar los servicios de GKE STUDYUP.","\u0e02\u0e49\u0e2d\u0e15\u0e01\u0e25\u0e07\u0e19\u0e35\u0e49\u0e23\u0e30\u0e1a\u0e38\u0e40\u0e07\u0e37\u0e48\u0e2d\u0e19\u0e44\u0e02\u0e41\u0e25\u0e30\u0e02\u0e31\u0e49\u0e19\u0e15\u0e2d\u0e19\u0e01\u0e32\u0e23\u0e43\u0e0a\u0e49\u0e1a\u0e23\u0e34\u0e01\u0e32\u0e23 GKE STUDYUP"],t.w)
B.a8M=new A.j(B.l,["\ubcf4\ud638\uc790 \ub3d9\uc758 \ud544\uc218","Parental Consent Required","\u4fdd\u8b77\u8005\u306e\u540c\u610f\u304c\u5fc5\u8981\u3067\u3059","\u9700\u8981\u76d1\u62a4\u4eba\u540c\u610f","Consentement parental requis","Elterliche Zustimmung erforderlich","\u0422\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f","\u0645\u0648\u0627\u0641\u0642\u0629 \u0648\u0644\u064a \u0627\u0644\u0623\u0645\u0631 \u0645\u0637\u0644\u0648\u0628\u0629","\u0905\u092d\u093f\u092d\u093e\u0935\u0915 \u0915\u0940 \u0938\u0939\u092e\u0924\u093f \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948","C\u1ea7n c\xf3 s\u1ef1 \u0111\u1ed3ng \xfd c\u1ee7a ph\u1ee5 huynh","Se requiere consentimiento parental","\u0e08\u0e33\u0e40\u0e1b\u0e47\u0e19\u0e15\u0e49\u0e2d\u0e07\u0e44\u0e14\u0e49\u0e23\u0e31\u0e1a\u0e04\u0e27\u0e32\u0e21\u0e22\u0e34\u0e19\u0e22\u0e2d\u0e21\u0e08\u0e32\u0e01\u0e1c\u0e39\u0e49\u0e1b\u0e01\u0e04\u0e23\u0e2d\u0e07"],t.w)
B.a91=new A.j(B.l,["\ubaa8\ub4e0 \uc815\ubcf4\ub294 \uc554\ud638\ud654\ub418\uc5b4 \uc548\uc804\ud558\uac8c \uad00\ub9ac\ub418\uba70, \uc0ac\uc6a9\uc790\ub294 \uc5b8\uc81c\ub4e0 \uc0ad\uc81c\ub97c \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","All information is securely encrypted (AES-256) and users retain the right to request deletion at any time.","\u3059\u3079\u3066\u306e\u60c5\u5831\u306fAES-256\u306b\u3088\u308a\u5b89\u5168\u306b\u6697\u53f7\u5316\u3055\u308c\u3001\u5229\u7528\u8005\u306f\u3044\u3064\u3067\u3082\u524a\u9664\u3092\u8981\u6c42\u3059\u308b\u6a29\u5229\u3092\u6709\u3057\u307e\u3059\u3002","\u6240\u6709\u4fe1\u606f\u5747\u901a\u8fc7AES-256\u52a0\u5bc6\u5b89\u5168\u4fdd\u5b58\uff0c\u7528\u6237\u53ef\u968f\u65f6\u8981\u6c42\u5220\u9664\u6570\u636e\u3002","Toutes les informations sont s\xe9curis\xe9es par un cryptage AES-256 et les utilisateurs conservent le droit de demander leur suppression \xe0 tout moment.","Alle Informationen werden sicher mit AES-256 verschl\xfcsselt, und Nutzer behalten das Recht, jederzeit die L\xf6schung zu verlangen.","\u0412\u0441\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u043d\u0430\u0434\u0451\u0436\u043d\u043e \u0437\u0430\u0448\u0438\u0444\u0440\u043e\u0432\u0430\u043d\u0430 (AES-256), \u0438 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442 \u043f\u0440\u0430\u0432\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0432 \u043b\u044e\u0431\u043e\u0435 \u0432\u0440\u0435\u043c\u044f.","\u064a\u062a\u0645 \u062a\u0634\u0641\u064a\u0631 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0628\u0623\u0645\u0627\u0646 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 AES-256\u060c \u0648\u064a\u062d\u062a\u0641\u0638 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0648\u0646 \u0628\u0627\u0644\u062d\u0642 \u0641\u064a \u0637\u0644\u0628 \u0627\u0644\u062d\u0630\u0641 \u0641\u064a \u0623\u064a \u0648\u0642\u062a.","\u0938\u092d\u0940 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 AES-256 \u0926\u094d\u0935\u093e\u0930\u093e \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0930\u0942\u092a \u0938\u0947 \u090f\u0928\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f \u0915\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948, \u0914\u0930 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u093f\u0938\u0940 \u092d\u0940 \u0938\u092e\u092f \u0939\u091f\u093e\u0928\u0947 \u0915\u093e \u0905\u0928\u0941\u0930\u094b\u0927 \u0915\u0930\u0928\u0947 \u0915\u093e \u0905\u0927\u093f\u0915\u093e\u0930 \u0930\u0916\u0924\u0947 \u0939\u0948\u0902\u0964","M\u1ecdi th\xf4ng tin \u0111\u1ec1u \u0111\u01b0\u1ee3c m\xe3 h\xf3a an to\xe0n b\u1eb1ng AES-256 v\xe0 ng\u01b0\u1eddi d\xf9ng c\xf3 quy\u1ec1n y\xeau c\u1ea7u x\xf3a d\u1eef li\u1ec7u b\u1ea5t c\u1ee9 l\xfac n\xe0o.","Toda la informaci\xf3n est\xe1 protegida con cifrado AES-256 y los usuarios conservan el derecho de solicitar su eliminaci\xf3n en cualquier momento.","\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14\u0e44\u0e14\u0e49\u0e23\u0e31\u0e1a\u0e01\u0e32\u0e23\u0e40\u0e02\u0e49\u0e32\u0e23\u0e2b\u0e31\u0e2a\u0e2d\u0e22\u0e48\u0e32\u0e07\u0e1b\u0e25\u0e2d\u0e14\u0e20\u0e31\u0e22\u0e14\u0e49\u0e27\u0e22 AES-256 \u0e41\u0e25\u0e30\u0e1c\u0e39\u0e49\u0e43\u0e0a\u0e49\u0e21\u0e35\u0e2a\u0e34\u0e17\u0e18\u0e34\u0e4c\u0e02\u0e2d\u0e43\u0e2b\u0e49\u0e25\u0e1a\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e44\u0e14\u0e49\u0e15\u0e25\u0e2d\u0e14\u0e40\u0e27\u0e25\u0e32"],t.w)
B.a97=new A.j(B.l,["\ubcf4\ud638\uc790\uc5d0\uac8c \uc778\uc99d\ubc88\ud638\uac00 \ubc1c\uc1a1\ub418\uc5c8\uc2b5\ub2c8\ub2e4!","Verification code sent to parent!","\u4fdd\u8b77\u8005\u306b\u8a8d\u8a3c\u756a\u53f7\u304c\u9001\u4fe1\u3055\u308c\u307e\u3057\u305f\uff01","\u9a8c\u8bc1\u7801\u5df2\u53d1\u9001\u7ed9\u76d1\u62a4\u4eba\uff01","Code envoy\xe9 au parent !","Best\xe4tigungscode wurde an den Elternteil gesendet!","\u041a\u043e\u0434 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044e!","\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0631\u0645\u0632 \u0627\u0644\u062a\u062d\u0642\u0642 \u0625\u0644\u0649 \u0648\u0644\u064a \u0627\u0644\u0623\u0645\u0631!","\u0905\u092d\u093f\u092d\u093e\u0935\u0915 \u0915\u094b \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0915\u094b\u0921 \u092d\u0947\u091c \u0926\u093f\u092f\u093e \u0917\u092f\u093e!","\u0110\xe3 g\u1eedi m\xe3 x\xe1c minh cho ph\u1ee5 huynh!","\xa1C\xf3digo enviado al padre/madre!","\u0e2a\u0e48\u0e07\u0e23\u0e2b\u0e31\u0e2a\u0e22\u0e37\u0e19\u0e22\u0e31\u0e19\u0e43\u0e2b\u0e49\u0e1c\u0e39\u0e49\u0e1b\u0e01\u0e04\u0e23\u0e2d\u0e07\u0e41\u0e25\u0e49\u0e27!"],t.w)
