B.XX=s(["\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0432 \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435 70 \u0431\u0430\u043b\u043b\u043e\u0432 \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u043d\u0435 \u0434\u043e\u0442\u044f\u0433\u0438\u0432\u0430\u0435\u0442 \u0434\u043e \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0443\u0440\u043e\u0432\u043d\u044f \u0443\u0447\u0435\u043d\u0438\u043a\u0430, \u0438 \u0435\u0441\u043b\u0438 \u043d\u0435 \u0443\u0441\u0442\u0440\u0430\u043d\u0438\u0442\u044c \u0442\u0435\u043a\u0443\u0449\u0438\u0435 \u0441\u043b\u0430\u0431\u043e\u0441\u0442\u0438, \u0435\u0441\u0442\u044c \u0440\u0438\u0441\u043a \u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f."],t.s)
B.Zh=s(["\u0647\u0630\u0647 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0641\u064a \u0627\u0644\u0633\u0628\u0639\u064a\u0646\u064a\u0627\u062a \u0623\u0642\u0644 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u0642\u062f\u0631\u0629 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u060c \u0648\u0625\u0647\u0645\u0627\u0644 \u0646\u0642\u0627\u0637 \u0627\u0644\u0636\u0639\u0641 \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0642\u062f \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0645\u0632\u064a\u062f \u0645\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639."],t.s)
